const STORAGE_KEY = "notepad-content";

let _beforeUnloadHandler = null;

export function load() {
    return localStorage.getItem(STORAGE_KEY);
}

export function save(content) {
    localStorage.setItem(STORAGE_KEY, content);
}

export function clear() {
    localStorage.removeItem(STORAGE_KEY);
}

export function enableUnloadPrompt() {
    if (!_beforeUnloadHandler) {
        _beforeUnloadHandler = (e) => {
            e.preventDefault();
        };
        window.addEventListener("beforeunload", _beforeUnloadHandler);
    }
}

export function disableUnloadPrompt() {
    if (_beforeUnloadHandler) {
        window.removeEventListener("beforeunload", _beforeUnloadHandler);
        _beforeUnloadHandler = null;
    }
}

@page "/notepad"
@rendermode InteractiveServer
@implements IAsyncDisposable
@inject IJSRuntime JS

<PageTitle>Notepad</PageTitle>

<script type="module" src="@Assets["Components/Pages/Notepad.razor.js"]"></script>

<h1>Notepad</h1>

<div class="mb-3">
    <textarea class="form-control" rows="12" @bind="content" @bind:event="oninput" placeholder="Type your notes here..."></textarea>
</div>

<div class="d-flex align-items-center gap-3 mb-3">
    <button class="btn btn-primary" @onclick="SaveNow">Save now</button>
    <button class="btn btn-outline-danger" @onclick="Clear">Clear</button>

    @if (lastSavedAt is not null)
    {
        <span class="text-muted">Last saved at @lastSavedAt.Value.ToString("HH:mm:ss")</span>
    }
</div>

@code {
    private string content = string.Empty;
    private string savedContent = string.Empty;
    private DateTime? lastSavedAt;
    private IJSObjectReference? module;
    private System.Threading.Timer? autoSaveTimer;

    private bool HasUnsavedChanges => content != savedContent;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            module = await JS.InvokeAsync<IJSObjectReference>("import",
                "./" + Assets["Components/Pages/Notepad.razor.js"]);

            var loaded = await module.InvokeAsync<string?>("load");
            if (loaded is not null)
            {
                content = loaded;
                savedContent = loaded;
                StateHasChanged();
            }

            autoSaveTimer = new System.Threading.Timer(async _ =>
            {
                await InvokeAsync(async () =>
                {
                    if (HasUnsavedChanges)
                    {
                        await SaveContent();
                        StateHasChanged();
                    }
                });
            }, null, TimeSpan.FromSeconds(30), TimeSpan.FromSeconds(30));
        }

        if (module is not null)
        {
            if (HasUnsavedChanges)
                await module.InvokeVoidAsync("enableUnloadPrompt");
            else
                await module.InvokeVoidAsync("disableUnloadPrompt");
        }
    }

    private async Task SaveContent()
    {
        if (module is null) return;
        await module.InvokeVoidAsync("save", content);
        savedContent = content;
        lastSavedAt = DateTime.Now;
    }

    private async Task SaveNow()
    {
        await SaveContent();
    }

    private async Task Clear()
    {
        if (module is null) return;
        content = string.Empty;
        savedContent = string.Empty;
        lastSavedAt = null;
        await module.InvokeVoidAsync("clear");
        await module.InvokeVoidAsync("disableUnloadPrompt");
    }

    public async ValueTask DisposeAsync()
    {
        if (autoSaveTimer is not null)
            await autoSaveTimer.DisposeAsync();

        if (module is not null)
        {
            try
            {
                await module.InvokeVoidAsync("disableUnloadPrompt");
                await module.DisposeAsync();
            }
            catch (JSDisconnectedException) { }
        }
    }
}

